// ICU 360 antimicrobial reference — types for src/data/antimicrobials.json (generated by the review dataset build).
export type AntimicrobialCategory = "Antibacterial" | "Antiviral" | "Antifungal" | "Antiparasitic";
export interface AntimicrobialDose { adult: string; severeICU: string | null; renal: string | null; hepatic: string | null; }
export interface AntimicrobialRef { code: string; source: string; }
export interface Antimicrobial {
  id: string; name: string; category: AntimicrobialCategory; drugClass: string; subclass: string;
  route: string[]; spectrum: string; indications: string[]; dose: AntimicrobialDose;
  contraindications: string[]; cautions: string[]; brandsIndia: string[]; aliases: string[];
  keywords: string[]; searchText: string; indiaAvailability: string; availabilityNote: string | null;
  approvalStatus: string; references: AntimicrobialRef[]; verify: boolean; verifyNote: string | null;
}
